using Astronomy.MediaFactory.Core.DocumentaryBlueprint;using Astronomy.MediaFactory.ProductionAdapters;using Microsoft.Extensions.Options;using Xunit;
namespace Astronomy.MediaFactory.Tests.ProductionAdapters;
public sealed class DocumentaryMediaVerificationNonMutationTests:IDisposable {
 readonly string root=Path.Combine(Path.GetTempPath(),"a39-"+Guid.NewGuid().ToString("N"));
 [Fact] public async Task Media_verification_does_not_modify_verified_artifact(){Directory.CreateDirectory(root);var attempts=Path.Combine(root,"attempts");var diagnostics=Path.Combine(root,"diagnostics");Directory.CreateDirectory(attempts);Directory.CreateDirectory(diagnostics);var path=Path.Combine(root,"final.wav");var bytes=new byte[]{1,2,3,4};await File.WriteAllBytesAsync(path,bytes);var checksum=await new DocumentaryChecksumService().ComputeSha256Async(path,default);var descriptor=new DocumentaryPhysicalArtifactDescriptor("audio","sha256:"+checksum,path,"audio/wav",bytes.Length,checksum,null,null,null,null,null,null,"producer",1,"correlation");var registry=new DocumentaryPhysicalArtifactRegistry();await registry.RegisterAsync(descriptor,DocumentaryPhysicalArtifactKind.NarrationAudio,default);var binding=new ProbeBinding(new(true,1000,false,true,false,AudioSampleRate:48000,AudioChannelCount:1,ContainerFormat:"wav"));var adapter=new DocumentaryProductionMediaVerificationAdapter(Options.Create(new DocumentaryMediaVerificationAdapterOptions{Enabled=true}),registry,new DocumentaryPhysicalArtifactDescriptorValidator(new DocumentaryContentIdentityFactory()),new DocumentaryChecksumService(),new DocumentaryMediaVerificationPolicyResolver(),new[]{binding},new DocumentaryMediaVerificationEvaluator(Options.Create(new DocumentaryMediaVerificationAdapterOptions())),new DocumentaryProductionDiagnosticsWriter(),new DocumentarySafeFileNameGenerator());var workspace=new DocumentaryProductionWorkspace(root,root,Path.Combine(root,"variants"),attempts,diagnostics);var request=new DocumentaryMediaVerificationRequest("audio",DocumentaryMediaAssetType.NarrationAudio,DocumentaryMediaAssetFormat.Wav,DocumentaryPhysicalArtifactKind.NarrationAudio,"correlation",1,ExpectedDurationMilliseconds:1000,ExpectedAudioSampleRate:48000,ExpectedAudioChannelCount:1,RequireAudio:true);var execution=new DocumentaryProductionExecutionContext("execution","correlation",DocumentaryProductionExecutionMode.Legacy,root,DateTimeOffset.UtcNow,new Dictionary<string,string>());var attempt=new DocumentaryProductionAttemptContext("execution","correlation",DocumentaryProductionOperationKind.MediaVerification,"audio",null,null,1,binding.ProviderId,DateTimeOffset.UtcNow,TimeSpan.FromSeconds(5));var beforeWrite=File.GetLastWriteTimeUtc(path);var result=await adapter.VerifyAsync(request,execution,attempt,workspace,default);Assert.True(result.Verified);Assert.Equal(bytes,await File.ReadAllBytesAsync(path));Assert.Equal(beforeWrite,File.GetLastWriteTimeUtc(path));Assert.Equal(descriptor,await registry.GetAsync("audio",default));Assert.Equal(checksum,await new DocumentaryChecksumService().ComputeSha256Async(path,default));Assert.Single(Directory.GetFiles(diagnostics));}
 public void Dispose(){if(Directory.Exists(root))Directory.Delete(root,true);}
 sealed class ProbeBinding(DocumentaryMediaProbeResult result):IDocumentaryMediaVerificationProviderBinding {public string ProviderId=>DocumentaryMediaVerificationProviderIds.ExistingFFprobeMediaVerifier;public Task<DocumentaryMediaVerificationProviderResponse> ProbeAsync(DocumentaryMediaVerificationProviderRequest request,CancellationToken token){token.ThrowIfCancellationRequested();return Task.FromResult(new DocumentaryMediaVerificationProviderResponse(true,result,null));}}
}
